int n = size;
for (int i = n / 2 - 1; i >= 0; i--) {
    std::swap(arr[i], arr[0]);
    int smallest = i;
    int left = 2 * i + 1;
    int right = 2 * i + 2;
    if (left < n && arr[left] < arr[smallest]) {
        smallest = left;
    }
    if (right < n && arr[right] < arr[smallest]) {
        smallest = right;
    }
    if (smallest != i) {
        std::swap(arr[i], arr[smallest]);
        int temp = smallest;
        while (temp < n) {
            smallest = temp;
            left = 2 * smallest + 1;
            right = 2 * smallest + 2;
            if (left < n && arr[left] < arr[smallest]) {
                smallest = left;
            }
            if (right < n && arr[right] < arr[smallest]) {
                smallest = right;
            }
            if (smallest == temp) {
                break;
            }
            std::swap(arr[temp], arr[smallest]);
            temp = smallest;
        }
    }
}

